3	namespace Illuminate\Queue;
4	
5	use Illuminate\Contracts\Cache\Repository as CacheContract;
6	use Illuminate\Contracts\Debug\ExceptionHandler;
7	use Illuminate\Contracts\Events\Dispatcher;
8	use Illuminate\Contracts\Queue\Factory as QueueManager;
9	use Illuminate\Database\DetectsLostConnections;
10	use Illuminate\Queue\Events\JobAttempted;
11	use Illuminate\Queue\Events\JobExceptionOccurred;
12	use Illuminate\Queue\Events\JobPopped;
13	use Illuminate\Queue\Events\JobPopping;
14	use Illuminate\Queue\Events\JobProcessed;
15	use Illuminate\Queue\Events\JobProcessing;
16	use Illuminate\Queue\Events\JobReleasedAfterException;
17	use Illuminate\Queue\Events\JobTimedOut;
18	use Illuminate\Queue\Events\Looping;
19	use Illuminate\Queue\Events\WorkerStopping;
20	use Illuminate\Support\Carbon;
21	use Throwable;
22	
23	class Worker
24	{
25	    use DetectsLostConnections;
26	
27	    const EXIT_SUCCESS = 0;
28	    const EXIT_ERROR = 1;
29	    const EXIT_MEMORY_LIMIT = 12;
30	
31	    /**
32	     * The name of the worker.
33	     *
34	     * @var string
35	     */
36	    protected $name;
37	
38	    /**
39	     * The queue manager instance.
40	     *
41	     * @var \Illuminate\Contracts\Queue\Factory
42	     */
43	    protected $manager;
44	
45	    /**
46	     * The event dispatcher instance.
47	     *
48	     * @var \Illuminate\Contracts\Events\Dispatcher
49	     */
50	    protected $events;
51	
52	    /**
53	     * The cache repository implementation.
54	     *
55	     * @var \Illuminate\Contracts\Cache\Repository
56	     */
57	    protected $cache;
58	
59	    /**
60	     * The exception handler instance.
61	     *
62	     * @var \Illuminate\Contracts\Debug\ExceptionHandler
63	     */
64	    protected $exceptions;
65	
66	    /**
67	     * The callback used to determine if the application is in maintenance mode.
68	     *
69	     * @var callable
70	     */
71	    protected $isDownForMaintenance;
72	
73	    /**
74	     * The callback used to reset the application's scope.
75	     *
76	     * @var callable
77	     */
78	    protected $resetScope;
79	
80	    /**
81	     * Indicates if the worker should exit.
82	     *
83	     * @var bool
84	     */
85	    public $shouldQuit = false;
86	
87	    /**
88	     * Indicates if the worker is paused.
89	     *
90	     * @var bool
91	     */
92	    public $paused = false;
93	
94	    /**
95	     * The callbacks used to pop jobs from queues.
96	     *
97	     * @var callable[]
98	     */
99	    protected static $popCallbacks = [];
100	
101	    /**
102	     * Create a new queue worker.
103	     *
104	     * @param  \Illuminate\Contracts\Queue\Factory  $manager
105	     * @param  \Illuminate\Contracts\Events\Dispatcher  $events
106	     * @param  \Illuminate\Contracts\Debug\ExceptionHandler  $exceptions
107	     * @param  callable  $isDownForMaintenance
108	     * @param  callable|null  $resetScope
109	     * @return void
110	     */
111	    public function __construct(
112	        QueueManager $manager,
113	        Dispatcher $events,
114	        ExceptionHandler $exceptions,
115	        callable $isDownForMaintenance,
116	        ?callable $resetScope = null,
117	    ) {
118	        $this->events = $events;
119	        $this->manager = $manager;
120	        $this->exceptions = $exceptions;
121	        $this->isDownForMaintenance = $isDownForMaintenance;
122	        $this->resetScope = $resetScope;
123	    }
124	
125	    /**
126	     * Listen to the given queue in a loop.
127	     *
128	     * @param  string  $connectionName
129	     * @param  string  $queue
130	     * @param  \Illuminate\Queue\WorkerOptions  $options
131	     * @return int
132	     */
133	    public function daemon($connectionName, $queue, WorkerOptions $options)
134	    {
135	        if ($supportsAsyncSignals = $this->supportsAsyncSignals()) {
136	            $this->listenForSignals();
137	        }
138	
139	        $lastRestart = $this->getTimestampOfLastQueueRestart();
140	
141	        [$startTime, $jobsProcessed] = [hrtime(true) / 1e9, 0];
142	
143	        while (true) {
144	            // Before reserving any jobs, we will make sure this queue is not paused and
145	            // if it is we will just pause this worker for a given amount of time and
146	            // make sure we do not need to kill this worker process off completely.
147	            if (! $this->daemonShouldRun($options, $connectionName, $queue)) {
148	                $status = $this->pauseWorker($options, $lastRestart);
149	
150	                if (! is_null($status)) {
151	                    return $this->stop($status, $options);
152	                }
153	
154	                continue;
155	            }
156	
157	            if (isset($this->resetScope)) {
158	                ($this->resetScope)();
159	            }
160	
161	            // First, we will attempt to get the next job off of the queue. We will also
162	            // register the timeout handler and reset the alarm for this job so it is
163	            // not stuck in a frozen state forever. Then, we can fire off this job.
164	            $job = $this->getNextJob(
165	                $this->manager->connection($connectionName), $queue
166	            );
167	
168	            if ($supportsAsyncSignals) {
169	                $this->registerTimeoutHandler($job, $options);
170	            }
171	
172	            // If the daemon should run (not in maintenance mode, etc.), then we can run
173	            // fire off this job for processing. Otherwise, we will need to sleep the
174	            // worker so no more jobs are processed until they should be processed.
175	            if ($job) {
176	                $jobsProcessed++;
177	
178	                $this->runJob($job, $connectionName, $options);
179	
180	                if ($options->rest > 0) {
181	                    $this->sleep($options->rest);
182	                }
183	            } else {
184	                $this->sleep($options->sleep);
185	            }
186	
187	            if ($supportsAsyncSignals) {
188	                $this->resetTimeoutHandler();
189	            }
190	
191	            // Finally, we will check to see if we have exceeded our memory limits or if
192	            // the queue should restart based on other indications. If so, we'll stop
193	            // this worker and let whatever is "monitoring" it restart the process.
194	            $status = $this->stopIfNecessary(
195	                $options, $lastRestart, $startTime, $jobsProcessed, $job
196	            );
197	
198	            if (! is_null($status)) {
199	                return $this->stop($status, $options);
200	            }
201	        }
202	    }
203	
204	    /**
205	     * Register the worker timeout handler.
206	     *
207	     * @param  \Illuminate\Contracts\Queue\Job|null  $job
208	     * @param  \Illuminate\Queue\WorkerOptions  $options
209	     * @return void
210	     */
211	    protected function registerTimeoutHandler($job, WorkerOptions $options)
212	    {
213	        // We will register a signal handler for the alarm signal so that we can kill this
214	        // process if it is running too long because it has frozen. This uses the async
215	        // signals supported in recent versions of PHP to accomplish it conveniently.
216	        pcntl_signal(SIGALRM, function () use ($job, $options) {
217	            if ($job) {
218	                $this->markJobAsFailedIfWillExceedMaxAttempts(
219	                    $job->getConnectionName(), $job, (int) $options->maxTries, $e = $this->timeoutExceededException($job)
220	                );
221	
222	                $this->markJobAsFailedIfWillExceedMaxExceptions(
223	                    $job->getConnectionName(), $job, $e
224	                );
225	
226	                $this->markJobAsFailedIfItShouldFailOnTimeout(
227	                    $job->getConnectionName(), $job, $e
228	                );
229	
230	                $this->events->dispatch(new JobTimedOut(
231	                    $job->getConnectionName(), $job
232	                ));
233	            }
234	
235	            $this->kill(static::EXIT_ERROR, $options);
236	        }, true);
237	
238	        pcntl_alarm(
239	            max($this->timeoutForJob($job, $options), 0)
240	        );
241	    }
242	
243	    /**
244	     * Reset the worker timeout handler.
245	     *
246	     * @return void
247	     */
248	    protected function resetTimeoutHandler()
249	    {
250	        pcntl_alarm(0);
251	    }
252	
253	    /**
254	     * Get the appropriate timeout for the given job.
255	     *
256	     * @param  \Illuminate\Contracts\Queue\Job|null  $job
257	     * @param  \Illuminate\Queue\WorkerOptions  $options
258	     * @return int
259	     */
260	    protected function timeoutForJob($job, WorkerOptions $options)
261	    {
262	        return $job && ! is_null($job->timeout()) ? $job->timeout() : $options->timeout;
263	    }
264	
265	    /**
266	     * Determine if the daemon should process on this iteration.
267	     *
268	     * @param  \Illuminate\Queue\WorkerOptions  $options
269	     * @param  string  $connectionName
270	     * @param  string  $queue
271	     * @return bool
272	     */
273	    protected function daemonShouldRun(WorkerOptions $options, $connectionName, $queue)
274	    {
275	        return ! ((($this->isDownForMaintenance)() && ! $options->force) ||
276	            $this->paused ||
277	            $this->events->until(new Looping($connectionName, $queue)) === false);
278	    }
279	
280	    /**
281	     * Pause the worker for the current loop.
282	     *
283	     * @param  \Illuminate\Queue\WorkerOptions  $options
284	     * @param  int  $lastRestart
285	     * @return int|null
286	     */
287	    protected function pauseWorker(WorkerOptions $options, $lastRestart)
288	    {
289	        $this->sleep($options->sleep > 0 ? $options->sleep : 1);
290	
291	        return $this->stopIfNecessary($options, $lastRestart);
292	    }
293	
294	    /**
295	     * Determine the exit code to stop the process if necessary.
296	     *
297	     * @param  \Illuminate\Queue\WorkerOptions  $options
298	     * @param  int  $lastRestart
299	     * @param  int  $startTime
300	     * @param  int  $jobsProcessed
301	     * @param  mixed  $job
302	     * @return int|null
303	     */
304	    protected function stopIfNecessary(WorkerOptions $options, $lastRestart, $startTime = 0, $jobsProcessed = 0, $job = null)
305	    {
306	        return match (true) {
307	            $this->shouldQuit => static::EXIT_SUCCESS,
308	            $this->memoryExceeded($options->memory) => static::EXIT_MEMORY_LIMIT,
309	            $this->queueShouldRestart($lastRestart) => static::EXIT_SUCCESS,
310	            $options->stopWhenEmpty && is_null($job) => static::EXIT_SUCCESS,
311	            $options->maxTime && hrtime(true) / 1e9 - $startTime >= $options->maxTime => static::EXIT_SUCCESS,
312	            $options->maxJobs && $jobsProcessed >= $options->maxJobs => static::EXIT_SUCCESS,
313	            default => null
314	        };
315	    }
316	
317	    /**
318	     * Process the next job on the queue.
319	     *
320	     * @param  string  $connectionName
321	     * @param  string  $queue
322	     * @param  \Illuminate\Queue\WorkerOptions  $options
323	     * @return void
324	     */
325	    public function runNextJob($connectionName, $queue, WorkerOptions $options)
326	    {
327	        $job = $this->getNextJob(
328	            $this->manager->connection($connectionName), $queue
329	        );
330	
331	        // If we're able to pull a job off of the stack, we will process it and then return
332	        // from this method. If there is no job on the queue, we will "sleep" the worker
333	        // for the specified number of seconds, then keep processing jobs after sleep.
334	        if ($job) {
335	            return $this->runJob($job, $connectionName, $options);
336	        }
337	
338	        $this->sleep($options->sleep);
339	    }
340	
341	    /**
342	     * Get the next job from the queue connection.
343	     *
344	     * @param  \Illuminate\Contracts\Queue\Queue  $connection
345	     * @param  string  $queue
346	     * @return \Illuminate\Contracts\Queue\Job|null
347	     */
348	    protected function getNextJob($connection, $queue)
349	    {
350	        $popJobCallback = function ($queue, $index = 0) use ($connection) {
351	            return $connection->pop($queue, $index);
352	        };
353	
354	        $this->raiseBeforeJobPopEvent($connection->getConnectionName());
355	
356	        try {
357	            if (isset(static::$popCallbacks[$this->name])) {
358	                if (! is_null($job = (static::$popCallbacks[$this->name])($popJobCallback, $queue))) {
359	                    $this->raiseAfterJobPopEvent($connection->getConnectionName(), $job);
360	                }
361	
362	                return $job;
363	            }
364	
365	            foreach (explode(',', $queue) as $index => $queue) {
366	                if (! is_null($job = $popJobCallback($queue, $index))) {
367	                    $this->raiseAfterJobPopEvent($connection->getConnectionName(), $job);
368	
369	                    return $job;
370	                }
371	            }
372	        } catch (Throwable $e) {
373	            $this->exceptions->report($e);
374	
375	            $this->stopWorkerIfLostConnection($e);
376	
377	            $this->sleep(1);
378	        }
379	    }
380	
381	    /**
382	     * Process the given job.
383	     *
384	     * @param  \Illuminate\Contracts\Queue\Job  $job
385	     * @param  string  $connectionName
386	     * @param  \Illuminate\Queue\WorkerOptions  $options
387	     * @return void
388	     */
389	    protected function runJob($job, $connectionName, WorkerOptions $options)
390	    {
391	        try {
392	            return $this->process($connectionName, $job, $options);
393	        } catch (Throwable $e) {
394	            $this->exceptions->report($e);
395	
396	            $this->stopWorkerIfLostConnection($e);
397	        }
398	    }
399	
400	    /**
401	     * Stop the worker if we have lost connection to a database.
402	     *
403	     * @param  \Throwable  $e
404	     * @return void
405	     */
406	    protected function stopWorkerIfLostConnection($e)
407	    {
408	        if ($this->causedByLostConnection($e)) {
409	            $this->shouldQuit = true;
410	        }
411	    }
412	
413	    /**
414	     * Process the given job from the queue.
415	     *
416	     * @param  string  $connectionName
417	     * @param  \Illuminate\Contracts\Queue\Job  $job
418	     * @param  \Illuminate\Queue\WorkerOptions  $options
419	     * @return void
420	     *
421	     * @throws \Throwable
422	     */
423	    public function process($connectionName, $job, WorkerOptions $options)
424	    {
425	        try {
426	            // First we will raise the before job event and determine if the job has already run
427	            // over its maximum attempt limits, which could primarily happen when this job is
428	            // continually timing out and not actually throwing any exceptions from itself.
429	            $this->raiseBeforeJobEvent($connectionName, $job);
430	
431	            $this->markJobAsFailedIfAlreadyExceedsMaxAttempts(
432	                $connectionName, $job, (int) $options->maxTries
433	            );
434	
435	            if ($job->isDeleted()) {
436	                return $this->raiseAfterJobEvent($connectionName, $job);
437	            }
438	
439	            // Here we will fire off the job and let it process. We will catch any exceptions, so
440	            // they can be reported to the developer's logs, etc. Once the job is finished the
441	            // proper events will be fired to let any listeners know this job has completed.
442	            $job->fire();
443	
444	            $this->raiseAfterJobEvent($connectionName, $job);
445	        } catch (Throwable $e) {
446	            $exceptionOccurred = true;
447	
448	            $this->handleJobException($connectionName, $job, $options, $e);
449	        } finally {
450	            $this->events->dispatch(new JobAttempted(
451	                $connectionName, $job, $exceptionOccurred ?? false
452	            ));
453	        }
454	    }
455	
456	    /**
457	     * Handle an exception that occurred while the job was running.
458	     *
459	     * @param  string  $connectionName
460	     * @param  \Illuminate\Contracts\Queue\Job  $job
461	     * @param  \Illuminate\Queue\WorkerOptions  $options
462	     * @param  \Throwable  $e
463	     * @return void
464	     *
465	     * @throws \Throwable
466	     */
467	    protected function handleJobException($connectionName, $job, WorkerOptions $options, Throwable $e)
468	    {
469	        try {
470	            // First, we will go ahead and mark the job as failed if it will exceed the maximum
471	            // attempts it is allowed to run the next time we process it. If so we will just
472	            // go ahead and mark it as failed now so we do not have to release this again.
473	            if (! $job->hasFailed()) {
474	                $this->markJobAsFailedIfWillExceedMaxAttempts(
475	                    $connectionName, $job, (int) $options->maxTries, $e
476	                );
477	
478	                $this->markJobAsFailedIfWillExceedMaxExceptions(
479	                    $connectionName, $job, $e
480	                );
481	            }
482	
483	            $this->raiseExceptionOccurredJobEvent(
484	                $connectionName, $job, $e
485	            );
486	        } finally {
487	            // If we catch an exception, we will attempt to release the job back onto the queue
488	            // so it is not lost entirely. This'll let the job be retried at a later time by
489	            // another listener (or this same one). We will re-throw this exception after.
490	            if (! $job->isDeleted() && ! $job->isReleased() && ! $job->hasFailed()) {
491	                $job->release($this->calculateBackoff($job, $options));
492	
493	                $this->events->dispatch(new JobReleasedAfterException(
494	                    $connectionName, $job
495	                ));
496	            }
497	        }
498	
499	        throw $e;
500	    }
501	
502	    /**
503	     * Mark the given job as failed if it has exceeded the maximum allowed attempts.
504	     *
505	     * This will likely be because the job previously exceeded a timeout.
506	     *
507	     * @param  string  $connectionName
508	     * @param  \Illuminate\Contracts\Queue\Job  $job
509	     * @param  int  $maxTries
510	     * @return void
511	     *
512	     * @throws \Throwable
513	     */
514	    protected function markJobAsFailedIfAlreadyExceedsMaxAttempts($connectionName, $job, $maxTries)
515	    {
516	        $maxTries = ! is_null($job->maxTries()) ? $job->maxTries() : $maxTries;
517	
518	        $retryUntil = $job->retryUntil();
519	
520	        if ($retryUntil && Carbon::now()->getTimestamp() <= $retryUntil) {
521	            return;
522	        }
523	
524	        if (! $retryUntil && ($maxTries === 0 || $job->attempts() <= $maxTries)) {
525	            return;
526	        }
527	
528	        $this->failJob($job, $e = $this->maxAttemptsExceededException($job));
529	
530	        throw $e;
531	    }
532	
533	    /**
534	     * Mark the given job as failed if it has exceeded the maximum allowed attempts.
535	     *
536	     * @param  string  $connectionName
537	     * @param  \Illuminate\Contracts\Queue\Job  $job
538	     * @param  int  $maxTries
539	     * @param  \Throwable  $e
540	     * @return void
541	     */
542	    protected function markJobAsFailedIfWillExceedMaxAttempts($connectionName, $job, $maxTries, Throwable $e)
543	    {
544	        $maxTries = ! is_null($job->maxTries()) ? $job->maxTries() : $maxTries;
545	
546	        if ($job->retryUntil() && $job->retryUntil() <= Carbon::now()->getTimestamp()) {
547	            $this->failJob($job, $e);
548	        }
549	
550	        if (! $job->retryUntil() && $maxTries > 0 && $job->attempts() >= $maxTries) {
551	            $this->failJob($job, $e);
552	        }
553	    }
554	
555	    /**
556	     * Mark the given job as failed if it has exceeded the maximum allowed attempts.
557	     *
558	     * @param  string  $connectionName
559	     * @param  \Illuminate\Contracts\Queue\Job  $job
560	     * @param  \Throwable  $e
561	     * @return void
562	     */
563	    protected function markJobAsFailedIfWillExceedMaxExceptions($connectionName, $job, Throwable $e)
564	    {
565	        if (! $this->cache || is_null($uuid = $job->uuid()) ||
566	            is_null($maxExceptions = $job->maxExceptions())) {
567	            return;
568	        }
569	
570	        if (! $this->cache->get('job-exceptions:'.$uuid)) {
571	            $this->cache->put('job-exceptions:'.$uuid, 0, Carbon::now()->addDay());
572	        }
573	
574	        if ($maxExceptions <= $this->cache->increment('job-exceptions:'.$uuid)) {
575	            $this->cache->forget('job-exceptions:'.$uuid);
576	
577	            $this->failJob($job, $e);
578	        }
579	    }
580	
581	    /**
582	     * Mark the given job as failed if it should fail on timeouts.
583	     *
584	     * @param  string  $connectionName
585	     * @param  \Illuminate\Contracts\Queue\Job  $job
586	     * @param  \Throwable  $e
587	     * @return void
588	     */
589	    protected function markJobAsFailedIfItShouldFailOnTimeout($connectionName, $job, Throwable $e)
590	    {
591	        if (method_exists($job, 'shouldFailOnTimeout') ? $job->shouldFailOnTimeout() : false) {
592	            $this->failJob($job, $e);
593	        }
594	    }
595	
596	    /**
597	     * Mark the given job as failed and raise the relevant event.
598	     *
599	     * @param  \Illuminate\Contracts\Queue\Job  $job
600	     * @param  \Throwable  $e
601	     * @return void
602	     */
603	    protected function failJob($job, Throwable $e)
604	    {
605	        $job->fail($e);
606	    }
607	
608	    /**
609	     * Calculate the backoff for the given job.
610	     *
611	     * @param  \Illuminate\Contracts\Queue\Job  $job
612	     * @param  \Illuminate\Queue\WorkerOptions  $options
613	     * @return int
614	     */
615	    protected function calculateBackoff($job, WorkerOptions $options)
616	    {
617	        $backoff = explode(
618	            ',',
619	            method_exists($job, 'backoff') && ! is_null($job->backoff())
620	                        ? $job->backoff()
621	                        : $options->backoff
622	        );
623	
624	        return (int) ($backoff[$job->attempts() - 1] ?? last($backoff));
625	    }
626	
627	    /**
628	     * Raise the before job has been popped.
629	     *
630	     * @param  string  $connectionName
631	     * @return void
