226	     * @param  \Illuminate\Contracts\Queue\Job  $job
227	     * @param  string  $status
228	     * @return void
229	     */
230	    protected function writeOutputForCli(Job $job, $status)
231	    {
232	        $this->output->write(sprintf(
233	            '  <fg=gray>%s</> %s%s',
234	            $this->now()->format('Y-m-d H:i:s'),
235	            $job->resolveName(),
236	            $this->output->isVerbose()
237	                ? sprintf(' <fg=gray>%s</>', $job->getJobId())
238	                : ''
239	        ));
240	
241	        if ($status == 'starting') {
242	            $this->latestStartedAt = microtime(true);
243	
244	            $dots = max(terminal()->width() - mb_strlen($job->resolveName()) - (
245	                $this->output->isVerbose() ? (mb_strlen($job->getJobId()) + 1) : 0
246	            ) - 33, 0);
247	
248	            $this->output->write(' '.str_repeat('<fg=gray>.</>', $dots));
249	
250	            return $this->output->writeln(' <fg=yellow;options=bold>RUNNING</>');
251	        }
252	
253	        $runTime = $this->runTimeForHumans($this->latestStartedAt);
254	
255	        $dots = max(terminal()->width() - mb_strlen($job->resolveName()) - (
256	            $this->output->isVerbose() ? (mb_strlen($job->getJobId()) + 1) : 0
257	        ) - mb_strlen($runTime) - 31, 0);
258	
259	        $this->output->write(' '.str_repeat('<fg=gray>.</>', $dots));
260	        $this->output->write(" <fg=gray>$runTime</>");
261	
262	        $this->output->writeln(match ($status) {
263	            'success' => ' <fg=green;options=bold>DONE</>',
