273	     * @param  string  $status
274	     * @param  Throwable|null  $exception
275	     * @return void
276	     */
277	    protected function writeOutputAsJson(Job $job, $status, ?Throwable $exception = null)
278	    {
279	        $log = array_filter([
280	            'level' => $status === 'starting' || $status === 'success' ? 'info' : 'warning',
281	            'id' => $job->getJobId(),
282	            'uuid' => $job->uuid(),
283	            'connection' => $job->getConnectionName(),
284	            'queue' => $job->getQueue(),
285	            'job' => $job->resolveName(),
286	            'status' => $status,
287	            'result' => match (true) {
288	                $job->isDeleted() => 'deleted',
289	                $job->isReleased() => 'released',
290	                $job->hasFailed() => 'failed',
291	                default => '',
292	            },
293	            'attempts' => $job->attempts(),
294	            'exception' => $exception ? $exception::class : '',
295	            'message' => $exception?->getMessage(),
296	            'timestamp' => $this->now()->format('Y-m-d\TH:i:s.uP'),
297	        ]);
298	
299	        if ($status === 'starting') {
300	            $this->latestStartedAt = microtime(true);
301	        } else {
302	            $log['duration'] = round(microtime(true) - $this->latestStartedAt, 6);
303	        }
304	
305	        $this->output->writeln(json_encode($log));
306	    }
