59	            'uuid' => $uuid = json_decode($payload, true)['uuid'],
60	            'connection' => $connection,
61	            'queue' => $queue,
62	            'payload' => $payload,
63	            'exception' => (string) mb_convert_encoding($exception, 'UTF-8'),
