70	    /**
71	     * Get the IDs of all of the failed jobs.
72	     *
73	     * @param  string|null  $queue
74	     * @return array
75	     */
76	    public function ids($queue = null)
77	    {
78	        return $this->getTable()
79	            ->when(! is_null($queue), fn ($query) => $query->where('queue', $queue))
80	            ->orderBy('id', 'desc')
81	            ->pluck('uuid')
82	            ->all();
83	    }
