public function testPruningFailedJobs()
{
    $provider = $this->getFailedJobProvider();

    Carbon::setTestNow(Carbon::createFromDate(2024, 4, 28));

    $provider->log('connection-1', 'queue-1', json_encode(['uuid' => 'uuid-1']), new RuntimeException());
